#include <iostream>
#include <string>
using namespace std;

class TextDocumentAnalysis {
public:
    static string input(const string& str) {
        int totalLength = str.length();
        bool insideParentheses = false;
        int totalWordsCount = 0;
        int maximumWordLength = 0;
        int currentWordLength = 0;
        for (int index = 0; index < totalLength; index++) {
            char character = str[index];
            if (character == '(') {
                if (currentWordLength > 0) {
                    if (currentWordLength > maximumWordLength) maximumWordLength = currentWordLength;
                    currentWordLength = 0;
                }
                insideParentheses = true;
            } else if (character == ')') {
                if (currentWordLength > 0) {
                    totalWordsCount++;
                    currentWordLength = 0;
                }
                insideParentheses = false;
            } else if (character == '_') {
                if (currentWordLength > 0) {
                    if (insideParentheses) {
                        totalWordsCount++;
                    } else {
                        if (currentWordLength > maximumWordLength) maximumWordLength = currentWordLength;
                    }
                    currentWordLength = 0;
                }
            } else {
                currentWordLength++;
            }
        }
        if (currentWordLength > 0) {
            if (insideParentheses) {
                totalWordsCount++;
            } else {
                if (currentWordLength > maximumWordLength) maximumWordLength = currentWordLength;
            }
        }
        return to_string(maximumWordLength) + " " + to_string(totalWordsCount);
    }
};

int main() {
    string line;
    while (getline(cin, line)) {
        // Read and ignore the first line as per original code
        // But in the original code, it reads a line and then reads the next line
        // So, to match that, we need to read two lines per iteration
        // But the Java code reads a line, then reads the next line for processing
        // So, we need to read and discard one line, then read the next for processing
        // Let's implement accordingly
        // Since the first getline already read a line, we need to read the next line
        // But if there's no next line, break
        string discardLine;
        if (!getline(cin, discardLine)) {
            break;
        }
        cout << TextDocumentAnalysis::input(discardLine) << endl;
    }
    return 0;
}

